#!/usr/bin/env bash
#
# Diff-size guard (T2). Keeps branches ticket-sized (odc-pipeline: one branch =
# one reviewable idea). Warns above WARN changed lines, fails above FAIL.
# Lockfiles and generated output are exempt from the count. Markdown is exempt
# too: specs (contracts/), ADRs and plans (docs/), and prose notes are governed
# by review, not a code line-budget — the phase-0 plan makes spec tickets (T3,
# T4) exempt from line limits, and this is where that exemption lives. Code
# (.ts, .go, config, scripts) is still fully counted.
#
# contracts/fixtures/** is exempt for the same reason as markdown, added in T5:
# the golden vectors are GENERATED byte-exact artifacts, reviewed by hand against
# the spec sentences they cite, not hand-written code competing for a line budget.
# One vector is one long line of NDJSON, so a complete conformance set would
# otherwise consume a whole ticket's allowance and force meaningless splits. The
# generator that produces them (tools/fixtures-gen) stays fully counted — the
# exemption covers the output, never the code.
#
# docs/mockups/** is exempt for the same reason as markdown: each file is one
# self-contained, hand-authored HTML deck, reviewed by eye against the design
# it renders, not against a code line-budget. Splitting a single deck across
# branches to dodge the ceiling would break the one-file-is-one-idea property
# that makes it reviewable at all.
#
# services/verifier/** and tools/verifier-ts/** are exempt (added at T7). Unlike
# ordinary code, each verifier is a HARD-ISOLATED, single-context, throwaway
# build: it is written from contracts/ alone in one fresh context (independence is
# the point — two verifiers must agree by construction), and its fixture suite is
# green ONLY when the whole verifier is present. Carving it into sub-ceiling
# stacked PRs produces intermediate branches that neither build nor pass the
# conformance tests, which breaks the "one PR = one REVIEWABLE idea" property this
# guard exists to protect — the same reasoning as the fixtures/mockups exemptions
# above, and it is why phase-0 dispatches each verifier as one ticket. The
# exemption is dir-scoped: it covers ONLY the two isolated verifier trees. Every
# other service, and the tools/ generators, stay fully counted.
#
# Run locally:  BASE=origin/master HEAD=HEAD bash .github/scripts/diff-size.sh
set -euo pipefail

BASE="${BASE:?BASE (base sha/ref) required}"
HEAD="${HEAD:?HEAD (head sha/ref) required}"

# 600 is the common industry ceiling for a reviewable diff; review quality is
# well documented to fall off past a few hundred lines, and 800 was set in T2
# before any real ticket had been measured against it. Lowered 800 → 600 in T5,
# which measured 2232 counted lines and split accordingly. Raised 600 → 1000
# after pulse work kept getting forced into artificially small branches that
# pushed review-relevant changes out of the PR they belonged to.
WARN=400
FAIL=1000

# added+deleted lines, excluding lockfiles, generated output, and markdown.
# Deletions count too (churn is churn) — a large legitimate removal can trip the
# ceiling and force a split; that's intended, keep removals on their own branch.
total=0
while IFS=$'\t' read -r add del _path; do
  # Binary files report '-' for both counts; skip them.
  [[ "$add" == "-" || "$del" == "-" ]] && continue
  total=$((total + add + del))
done < <(git diff --numstat "$BASE...$HEAD" -- . \
  ':(exclude)pnpm-lock.yaml' \
  ':(exclude)package-lock.json' \
  ':(exclude)yarn.lock' \
  ':(exclude,glob)**/dist/**' \
  ':(exclude,glob)**/.turbo/**' \
  ':(exclude,glob)contracts/fixtures/**' \
  ':(exclude,glob)docs/mockups/**' \
  ':(exclude,glob)services/verifier/**' \
  ':(exclude,glob)tools/verifier-ts/**' \
  ':(exclude,glob)**/*.md')

echo "Changed lines (excluding lockfiles/generated/markdown/mockups): $total"

if ((total > FAIL)); then
  echo "::error::Diff is $total changed lines (> $FAIL). Split or stack this branch (odc-pipeline)."
  exit 1
elif ((total > WARN)); then
  echo "::warning::Diff is $total changed lines (> $WARN). Target is < $WARN; consider splitting."
fi

echo "diff-size OK."
